import{_ as a,o as t,c as n,a2 as l}from"./chunks/framework.BZO4qERu.js";const d=JSON.parse('{"title":"Channels","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/channels/index.md","filePath":"integrations/channels/index.md","lastUpdated":1790952322000}'),o={name:"integrations/channels/index.md"};function i(r,e,s,h,c,p){return t(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h1><p>Channels connect Memoh bots to messaging platforms. Configure them from the bot <strong>Platforms</strong> tab so users can talk to the same bot through Slack, Telegram, Feishu, Discord, WeChat, and other platforms, as well as directly in the Memoh app.</p><h2 id="supported-channels" tabindex="-1">Supported channels <a class="header-anchor" href="#supported-channels" aria-label="Permalink to &quot;Supported channels&quot;">​</a></h2><ul><li><a href="./telegram.html">Telegram</a></li><li><a href="./slack.html">Slack</a></li><li><a href="./discord.html">Discord</a></li><li><a href="./feishu.html">Feishu (Lark)</a></li><li><a href="./dingtalk.html">DingTalk</a></li><li><a href="./wecom.html">WeCom</a></li><li><a href="./weixin.html">WeChat</a></li><li><a href="./qq.html">QQ</a></li><li><a href="./line.html">LINE</a></li></ul><p>What each channel supports (Markdown, attachments, streaming, group chats, and so on) is noted in the Limits section of its page.</p><h2 id="general-setup-flow" tabindex="-1">General Setup Flow <a class="header-anchor" href="#general-setup-flow" aria-label="Permalink to &quot;General Setup Flow&quot;">​</a></h2><ol><li>Register an app or bot on the target platform.</li><li>Obtain credentials such as API tokens, app IDs, app secrets, or access tokens.</li><li>Add the channel from the bot <strong>Platforms</strong> tab in Memoh.</li><li>Save and enable the channel.</li></ol><p>Depending on the platform, the final step may involve copying a webhook callback URL into the platform console, approving a QR login on mobile, or keeping a stream/WebSocket connection running through Memoh.</p>',8)])])}const f=a(o,[["render",i]]);export{d as __pageData,f as default};
